def chip_fire(D, adj, v):
    result = D.copy()
    deg = int(adj[v].sum())
    result[v] -= deg
    for w in range(len(D)):
        if adj[v,w] > 0:
            result[w] += 1
    return result

def dhars_burning(D, adj, q):
    n = len(D)
    burnt = {q}
    changed = True
    while changed:
        changed = False
        for v in range(n):
            if v in burnt: continue
            bn = sum(1 for w in burnt if adj[v,w] > 0)
            if bn > D[v]:
                burnt.add(v)
                changed = True
    return len(burnt) == n, burnt

def q_reduce(D, adj, q, max_iter=100000):
    n = len(D)
    current = D.copy()
    for _ in range(max_iter):
        is_red, burnt = dhars_burning(current, adj, q)
        if is_red: return current
        unburnt = set(range(n)) - burnt
        for v in unburnt:
            current = chip_fire(current, adj, v)
    return None
